  9→namespace Magento\JwtUserToken\Model;
 10→
 11→use Magento\Authorization\Model\UserContextInterface;
 12→use Magento\Framework\Jwt\Claim\ExpirationTime;
 13→use Magento\Framework\Jwt\Claim\IssuedAt;
 14→use Magento\Framework\Jwt\Claim\PrivateClaim;
 15→use Magento\Framework\Jwt\Jwe\Jwe;
 16→use Magento\Framework\Jwt\Jwe\JweHeader;
 17→use Magento\Framework\Jwt\Jws\Jws;
 18→use Magento\Framework\Jwt\Jws\JwsHeader;
 19→use Magento\Framework\Jwt\Jws\JwsSignatureSettingsInterface;
 20→use Magento\Framework\Jwt\JwtManagerInterface;
 21→use Magento\Framework\Jwt\Payload\ClaimsPayload;
 22→use Magento\Integration\Api\Data\UserTokenParametersInterface;
 23→use Magento\Integration\Api\Exception\UserTokenException;
 24→use Magento\Integration\Api\UserTokenIssuerInterface;
 25→use Magento\JwtUserToken\Api\ConfigReaderInterface;
 26→use Magento\JwtUserToken\Model\Data\JwtTokenParameters;
 27→
 28→class Issuer implements UserTokenIssuerInterface
 29→{
 30→    /**
 31→     * @var JwtManagerInterface
 32→     */
 33→    private $jwtManager;
 34→
 35→    /**
 36→     * @var JwtSettingsProviderInterface
 37→     */
 38→    private $settingsProvider;
 39→
 40→    /**
 41→     * @var ConfigReaderInterface
 42→     */
 43→    private $configReader;
 44→
 45→    /**
 46→     * @param JwtManagerInterface $jwtManager
 47→     * @param JwtSettingsProviderInterface $settingsProvider
 48→     * @param ConfigReaderInterface $configReader
 49→     */
 50→    public function __construct(
 51→        JwtManagerInterface $jwtManager,
 52→        JwtSettingsProviderInterface $settingsProvider,
 53→        ConfigReaderInterface $configReader
 54→    ) {
 55→        $this->jwtManager = $jwtManager;
 56→        $this->settingsProvider = $settingsProvider;
 57→        $this->configReader = $configReader;
 58→    }
 59→
 60→    /**
 61→     * @inheritDoc
 62→     */
 63→    public function create(UserContextInterface $userContext, UserTokenParametersInterface $params): string
 64→    {
 65→        if (!$userContext->getUserId() || !$userContext->getUserType()) {
 66→            throw new UserTokenException('User ID and Type ID cannot be empty');
 67→        }
 68→
 69→        $protectedHeaders = [];
 70→        $publicHeaders = [];
 71→        $claims = [];
 72→        $claims['uid'] = new PrivateClaim('uid', (int) $userContext->getUserId());
 73→        $claims['utypid'] = new PrivateClaim('utypid', (int) $userContext->getUserType());
 74→        if ($params->getForcedIssuedTime()) {
 75→            $iat = $params->getForcedIssuedTime();
 76→            if ($iat instanceof \DateTime) {
 77→                $iat = \DateTimeImmutable::createFromMutable($iat);
 78→            }
 79→        } else {
 80→            $iat = new \DateTimeImmutable('now', new \DateTimeZone('UTC'));
 81→        }
 82→        $claims['iat'] = new IssuedAt($iat, true);
 83→        if ($userContext->getUserType() === UserContextInterface::USER_TYPE_ADMIN) {
 84→            $ttl = $this->configReader->getAdminTtl();
 85→        } elseif ($userContext->getUserType() === UserContextInterface::USER_TYPE_CUSTOMER) {
 86→            $ttl = $this->configReader->getCustomerTtl();
 87→        } else {
 88→            throw new \RuntimeException('Can only issue tokens for customers and admin users');
 89→        }
 90→        $claims['exp'] = new ExpirationTime($iat->add(new \DateInterval("PT{$ttl}M")), true);
 91→
 92→        if ($jwtParams = $params->getExtensionAttributes()->getJwtParams()) {
 93→            /** @var JwtTokenParameters $jwtParams */
 94→            $protectedHeaders = array_merge($jwtParams->getProtectedHeaderParameters(), $protectedHeaders);
 95→            $publicHeaders = array_merge($jwtParams->getPublicHeaderParameters(), $publicHeaders);
 96→            $claims = array_merge($jwtParams->getClaims(), $claims);
 97→        }
 98→
 99→        $settings = $this->settingsProvider->prepareSettingsFor($userContext);
100→        if ($settings instanceof JwsSignatureSettingsInterface) {
101→            return $this->jwtManager->create(
102→                new Jws(
103→                    [new JwsHeader($protectedHeaders)],
104→                    new ClaimsPayload($claims),
105→                    $publicHeaders ? [new JwsHeader($publicHeaders)] : null
106→                ),
107→                $settings
108→            );
109→        } else {
110→            return $this->jwtManager->create(
111→                new Jwe(
112→                    new JweHeader($protectedHeaders),
113→                    new JweHeader($publicHeaders),
114→                    null,
115→                    new ClaimsPayload($claims)
116→                ),
117→                $settings
118→            );
119→        }
120→    }
121→}
