  9→namespace Magento\JwtUserToken\Model;
 10→
 11→use Magento\Framework\Jwt\Exception\JwtException;
 12→use Magento\Framework\Jwt\HeaderInterface;
 13→use Magento\Framework\Jwt\HeaderParameterInterface;
 14→use Magento\Framework\Jwt\Jwe\JweInterface;
 15→use Magento\Framework\Jwt\Jws\JwsInterface;
 16→use Magento\Framework\Jwt\JwtManagerInterface;
 17→use Magento\Framework\Jwt\Payload\ClaimsPayloadInterface;
 18→use Magento\Integration\Api\Data\UserToken;
 19→use Magento\Integration\Api\Exception\UserTokenException;
 20→use Magento\Integration\Api\UserTokenReaderInterface;
 21→use Magento\JwtUserToken\Model\Data\Header;
 22→use Magento\JwtUserToken\Model\Data\JwtTokenData;
 23→use Magento\JwtUserToken\Model\Data\JwtUserContext;
 24→
 25→class Reader implements UserTokenReaderInterface
 26→{
 27→    /**
 28→     * @var JwtSettingsProviderInterface
 29→     */
 30→    private $settingsProvider;
 31→
 32→    /**
 33→     * @var JwtManagerInterface
 34→     */
 35→    private $jwtManager;
 36→
 37→    /**
 38→     * @param JwtManagerInterface $jwtManager
 39→     * @param JwtSettingsProviderInterface $settingsProvider
 40→     */
 41→    public function __construct(JwtManagerInterface $jwtManager, JwtSettingsProviderInterface $settingsProvider)
 42→    {
 43→        $this->jwtManager = $jwtManager;
 44→        $this->settingsProvider = $settingsProvider;
 45→    }
 46→
 47→    /**
 48→     * @inheritDoc
 49→     */
 50→    public function read(string $token): UserToken
 51→    {
 52→        try {
 53→            $jwt = $this->jwtManager->read($token, $this->settingsProvider->prepareAllAccepted());
 54→        } catch (JwtException $exception) {
 55→            throw new UserTokenException('Failed to read JWT token', $exception);
 56→        }
 57→
 58→        if ($jwt instanceof JwsInterface) {
 59→            $headerParams = array_merge(
 60→                $this->extractHeaderParameters($jwt->getProtectedHeaders()),
 61→                $this->extractHeaderParameters($jwt->getUnprotectedHeaders())
 62→            );
 63→        } elseif ($jwt instanceof JweInterface) {
 64→            $headerParams = array_merge(
 65→                $this->extractHeaderParameters($jwt->getPerRecipientUnprotectedHeaders()),
 66→                $this->extractHeaderParameters($jwt->getSharedUnprotectedHeader()),
 67→                $this->extractHeaderParameters($jwt->getProtectedHeader())
 68→            );
 69→        } else {
 70→            $headerParams = $this->extractHeaderParameters($jwt->getHeader());
 71→        }
 72→
 73→        if (!$jwt->getPayload() instanceof ClaimsPayloadInterface) {
 74→            throw new UserTokenException('JWT does not contain claims');
 75→        }
 76→        /** @var ClaimsPayloadInterface $payload */
 77→        $payload = $jwt->getPayload();
 78→        $claims = $payload->getClaims();
 79→        if (empty($claims['uid']) || empty($claims['uid']->getValue())) {
 80→            throw new UserTokenException('UserId (uid) time not provided by the received JWT');
 81→        }
 82→        if (empty($claims['utypid']) || empty($claims['utypid']->getValue())) {
 83→            throw new UserTokenException('UserTypeId (utypid) time not provided by the received JWT');
 84→        }
 85→        if (empty($claims['iat']) || empty($claims['iat']->getValue())) {
 86→            throw new UserTokenException('IssuedAt (iat) time not provided by the received JWT');
 87→        }
 88→        $iat = \DateTimeImmutable::createFromFormat('U', (string) $claims['iat']->getValue());
 89→        if (empty($claims['exp']) || empty($claims['exp']->getValue())) {
 90→            throw new UserTokenException('ExpiresAt (exp) time not provided by the received JWT');
 91→        }
 92→        $exp = \DateTimeImmutable::createFromFormat('U', (string) $claims['exp']->getValue());
 93→
 94→        return new UserToken(
 95→            new JwtUserContext((int) $claims['uid']->getValue(), (int) $claims['utypid']->getValue()),
 96→            new JwtTokenData($iat, $exp, new Header($headerParams), $payload)
 97→        );
 98→    }
 99→
100→    /**
101→     * Extract header values from multiple headers.
102→     *
103→     * @param HeaderInterface|HeaderInterface[]|null $headers
104→     * @return HeaderParameterInterface[]
105→     */
106→    private function extractHeaderParameters($headers): array
107→    {
108→        $params = [];
109→        if ($headers) {
110→            if (!is_array($headers)) {
111→                $headers = [$headers];
112→            }
113→
114→            foreach ($headers as $header) {
115→                foreach ($header->getParameters() as $parameter) {
116→                    $params[$parameter->getName()] = $parameter;
117→                }
118→            }
119→        }
120→
121→        return $params;
122→    }
123→}
