16→/**
17→ * Verifies that tokens were not revoked.
18→ */
19→class RevokedValidator implements UserTokenValidatorInterface
20→{
21→    /**
22→     * @var RevokedRepositoryInterface
23→     */
24→    private $revokedRepo;
25→
26→    /**
27→     * @param RevokedRepositoryInterface $revokedRepo
28→     */
29→    public function __construct(RevokedRepositoryInterface $revokedRepo)
30→    {
31→        $this->revokedRepo = $revokedRepo;
32→    }
33→
34→    /**
35→     * @inheritDoc
36→     */
37→    public function validate(UserToken $token): void
38→    {
39→        $revoked = $this->revokedRepo->findRevoked(
40→            (int) $token->getUserContext()->getUserType(),
41→            (int) $token->getUserContext()->getUserId()
42→        );
43→
44→        if ($revoked && $token->getData()->getIssued()->getTimestamp() <= $revoked->getBeforeTimestamp()) {
45→            throw new AuthorizationException(__('User token has been revoked'));
46→        }
47→    }
48→}
