  7→namespace Magento\Webapi\Model\Authorization;
  8→
  9→use Magento\Authorization\Model\UserContextInterface;
 10→use Magento\Framework\App\ObjectManager;
 11→use Magento\Framework\Exception\AuthorizationException;
 12→use Magento\Framework\ObjectManager\ResetAfterRequestInterface;
 13→use Magento\Integration\Api\Exception\UserTokenException;
 14→use Magento\Integration\Api\UserTokenReaderInterface;
 15→use Magento\Integration\Api\UserTokenValidatorInterface;
 16→use Magento\Integration\Model\Oauth\Token;
 17→use Magento\Integration\Model\Oauth\TokenFactory;
 18→use Magento\Integration\Api\IntegrationServiceInterface;
 19→use Magento\Framework\Webapi\Request;
 20→use Magento\Framework\Stdlib\DateTime\DateTime as Date;
 21→use Magento\Framework\Stdlib\DateTime;
 22→use Magento\Integration\Helper\Oauth\Data as OauthHelper;
 23→
 24→/**
 25→ * A user context determined by tokens in a HTTP request Authorization header.
 26→ *
 27→ * @SuppressWarnings(PHPMD.CouplingBetweenObjects)
 28→ * @SuppressWarnings(PHPMD.UnusedFormalParameter)
 29→ */
 30→class TokenUserContext implements UserContextInterface, ResetAfterRequestInterface
 31→{
 32→    /**
 33→     * @var Request
 34→     */
 35→    protected $request;
 36→
 37→    /**
 38→     * @var Token
 39→     */
 40→    protected $tokenFactory;
 41→
 42→    /**
 43→     * @var int
 44→     */
 45→    protected $userId;
 46→
 47→    /**
 48→     * @var string
 49→     */
 50→    protected $userType;
 51→
 52→    /**
 53→     * @var bool
 54→     */
 55→    protected $isRequestProcessed;
 56→
 57→    /**
 58→     * @var IntegrationServiceInterface
 59→     */
 60→    protected $integrationService;
 61→
 62→    /**
 63→     * @var UserTokenReaderInterface
 64→     *
 65→     * phpcs:disable Magento2.Commenting.ClassPropertyPHPDocFormatting
 66→     */
 67→    private readonly UserTokenReaderInterface $userTokenReader;
 68→
 69→    /**
 70→     * @var UserTokenValidatorInterface
 71→     *
 72→     * phpcs:disable Magento2.Commenting.ClassPropertyPHPDocFormatting
 73→     */
 74→    private readonly UserTokenValidatorInterface $userTokenValidator;
 75→
 76→    /**
 77→     * Initialize dependencies.
 78→     *
 79→     * @param Request $request
 80→     * @param TokenFactory $tokenFactory
 81→     * @param IntegrationServiceInterface $integrationService
 82→     * @param DateTime|null $dateTime
 83→     * @param Date|null $date
 84→     * @param OauthHelper|null $oauthHelper
 85→     * @param UserTokenReaderInterface|null $tokenReader
 86→     * @param UserTokenValidatorInterface|null $tokenValidator
 87→     */
 88→    public function __construct(
 89→        \Magento\Framework\App\RequestInterface $request,
 90→        TokenFactory $tokenFactory,
 91→        IntegrationServiceInterface $integrationService,
 92→        ?DateTime $dateTime = null,
 93→        ?Date $date = null,
 94→        ?OauthHelper $oauthHelper = null,
 95→        ?UserTokenReaderInterface $tokenReader = null,
 96→        ?UserTokenValidatorInterface $tokenValidator = null
 97→    ) {
 98→        $this->request = $request;
 99→        $this->tokenFactory = $tokenFactory;
100→        $this->integrationService = $integrationService;
101→        $this->userTokenReader = $tokenReader ?? ObjectManager::getInstance()->get(UserTokenReaderInterface::class);
102→        $this->userTokenValidator = $tokenValidator
103→            ?? ObjectManager::getInstance()->get(UserTokenValidatorInterface::class);
104→    }
105→
106→    /**
107→     * @inheritdoc
108→     */
109→    public function getUserId()
110→    {
111→        $this->processRequest();
112→        return $this->userId;
113→    }
114→
115→    /**
116→     * @inheritdoc
117→     */
118→    public function getUserType()
119→    {
120→        $this->processRequest();
121→        return $this->userType;
122→    }
123→
124→    /**
125→     * Finds the bearer token and looks up the value.
126→     *
127→     * @return void
128→     */
129→    protected function processRequest()
130→    {
131→        if ($this->isRequestProcessed) {
132→            return;
133→        }
134→
135→        $authorizationHeaderValue = $this->request->getHeader('Authorization');
136→        if (!$authorizationHeaderValue) {
137→            $this->isRequestProcessed = true;
138→            return;
139→        }
140→
141→        $headerPieces = explode(" ", $authorizationHeaderValue);
142→        if (count($headerPieces) !== 2) {
143→            $this->isRequestProcessed = true;
144→            return;
145→        }
146→
147→        $tokenType = strtolower($headerPieces[0]);
148→        if ($tokenType !== 'bearer') {
149→            $this->isRequestProcessed = true;
150→            return;
151→        }
152→
153→        $bearerToken = $headerPieces[1];
154→        try {
155→            $token = $this->userTokenReader->read($bearerToken);
156→        } catch (UserTokenException $exception) {
157→            $this->isRequestProcessed = true;
158→            return;
159→        }
160→        try {
161→            $this->userTokenValidator->validate($token);
162→        } catch (AuthorizationException $exception) {
163→            $this->isRequestProcessed = true;
164→            return;
165→        }
166→
167→        $this->userType = $token->getUserContext()->getUserType();
168→        $this->userId = $token->getUserContext()->getUserId();
169→        $this->isRequestProcessed = true;
170→    }
171→
172→    /**
173→     * Set user data based on user type received from token data.
174→     *
175→     * @param Token $token
176→     * @return void
177→     * @deprecated Since tokens are handled with UserTokenReader now.
178→     * @see TokenUserContext::processRequest()
179→     */
180→    protected function setUserDataViaToken(Token $token)
181→    {
182→        $this->userType = $token->getUserType();
183→        switch ($this->userType) {
184→            case UserContextInterface::USER_TYPE_INTEGRATION:
185→                $this->userId = $this->integrationService->findByConsumerId($token->getConsumerId())->getId();
186→                $this->userType = UserContextInterface::USER_TYPE_INTEGRATION;
187→                break;
188→            case UserContextInterface::USER_TYPE_ADMIN:
189→                $this->userId = $token->getAdminId();
190→                $this->userType = UserContextInterface::USER_TYPE_ADMIN;
191→                break;
192→            case UserContextInterface::USER_TYPE_CUSTOMER:
193→                $this->userId = $token->getCustomerId();
194→                $this->userType = UserContextInterface::USER_TYPE_CUSTOMER;
195→                break;
196→            default:
197→                /* this is an unknown user type so reset the cached user type */
198→                $this->userType = null;
199→        }
200→    }
201→
202→    /**
203→     * @inheritDoc
204→     */
205→    public function _resetState(): void
206→    {
207→        $this->isRequestProcessed = null;
208→        $this->userId = null;
209→        $this->userType = null;
210→    }
211→}
